import{_ as t,o as a,c as o,a9 as i}from"./chunks/framework.AY-u9rel.js";const h=JSON.parse(`{"title":"Product and Audience","description":"Feluqa's product model, the people who interact with it, and the responsibilities shared between an application and its platform.","frontmatter":{"sidebarTitle":"Product & Audience","icon":"users","title":"Product and Audience","description":"Feluqa's product model, the people who interact with it, and the responsibilities shared between an application and its platform.","summary":"Explains Feluqa's product-first model, in which Applications combine business Modules and may expose different interfaces, including console and desktop experiences. It identifies the concerns of product owners, technical teams, operators, and end users, separates application responsibilities from shared platform services, and marks workstation and runtime capabilities as goals where they are not yet implemented.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":2,"status":"Exploring","tags":["feluqa","product","audience","modules"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"get-started/introduction/product-and-audience.md","filePath":"get-started/introduction/product-and-audience.md"}`),n={name:"get-started/introduction/product-and-audience.md"};function s(r,e,d,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="product-and-audience" tabindex="-1">Product and Audience <a class="header-anchor" href="#product-and-audience" aria-label="Permalink to &quot;Product and Audience&quot;">​</a></h1><h2 id="a-product-first-model" tabindex="-1">A product-first model <a class="header-anchor" href="#a-product-first-model" aria-label="Permalink to &quot;A product-first model&quot;">​</a></h2><p>Feluqa treats a module as a product: a self-contained unit of business functionality with its own identity, version, permissions, and switchable features. An application can combine several modules, or a module can be shipped on its own.</p><p>This model aims to make it possible to:</p><ul><li>focus application work on business rules and workflows while the platform provides shared services such as authentication, access control, and audit;</li><li>offer modules independently and enable features for specific customers;</li><li>reuse a module in a hosted application or a standalone workstation.</li></ul><p>These are product goals; Feluqa does not yet provide every runtime or module lifecycle capability needed to deliver them.</p><p>Feluqa products may offer console workflows through more than a conventional terminal window. A desktop product could present a terminal as its primary interface, or provide a terminal inside a graphical desktop application. These are distinct product experiences: the first hosts a console interface in a desktop window, while the second combines graphical workflows with an integrated console. Both are product directions, not capabilities currently available in the current release.</p><h2 id="who-uses-feluqa" tabindex="-1">Who uses Feluqa <a class="header-anchor" href="#who-uses-feluqa" aria-label="Permalink to &quot;Who uses Feluqa&quot;">​</a></h2><p>People encounter Feluqa in different ways. A founder or product owner may be interested in the product model, while a technical lead or developer may work with the project and its code. Operators install and run applications, and end users work with the resulting application.</p><table tabindex="0"><thead><tr><th>Role</th><th>What they do</th><th>What they see</th></tr></thead><tbody><tr><td><strong>Product builder</strong></td><td>Shapes and develops modules and applications.</td><td>The project and its tools, including the Feluqa CLI.</td></tr><tr><td><strong>Operator</strong></td><td>Installs, configures, and runs an application on a server or device.</td><td>The CLI and, as it is completed, the built-in System panel.</td></tr><tr><td><strong>End user</strong></td><td>Uses an application.</td><td>Its interface on a browser, workstation, phone, or other supported device.</td></tr><tr><td><strong>Feluqa contributor</strong></td><td>Helps improve Feluqa.</td><td>The contribution process and, when authorized, the relevant source code.</td></tr></tbody></table><p>You do not need to contribute to Feluqa itself to understand or use an application built with it.</p><h2 id="application-responsibilities" tabindex="-1">Application responsibilities <a class="header-anchor" href="#application-responsibilities" aria-label="Permalink to &quot;Application responsibilities&quot;">​</a></h2><p>Application code defines the business side:</p><ul><li>domain models, rules, and workflows;</li><li>resources and the screens used to manage them;</li><li>permissions, roles, and policies;</li><li>modules, submodules, and features.</li></ul><p>Feluqa provides shared building blocks, including an SDK, compile-time validation and generation, a CLI, storage integrations, and platform services. The architecture overview and relevant capability guides distinguish implemented behavior from remaining product goals.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p><strong>Business software.</strong> A sales module could expose an API on a server and share its business rules with a workstation application.</p><p><strong>Field workstations.</strong> An application could keep essential functions and local data available when connectivity is limited or unavailable.</p><p><strong>IoT and ground systems.</strong> A module could collect and process telemetry locally and expose relevant information to an operator. Protocol support depends on the integration implemented for each target.</p><p><strong>Several offers, one codebase.</strong> A product could provide a base set of features and enable additional features for customers who license them.</p>',20)])])}const m=t(n,[["render",s]]);export{h as __pageData,m as default};
